def r(k, tags, g, f, regra_txt, m, fx, sol, alt, erro_txt=None, certo_txt=None, esq=None, refs=(), alvo=None):
    """Rápido compacto: regra + (erro no Errado | certo opcional) + esquema opcional + Memorize."""
    if g == 'E' and not erro_txt:
        raise ValueError(f'{k}: Errado precisa do bloco erro')
    b = [regra(regra_txt)] + ([erro(erro_txt)] if erro_txt else []) + ([certo(certo_txt)] if certo_txt else []) \
        + ([esquema(esq)] if esq else [])
    alvo = alvo or m
    return dict(k=k, tags=tags, g=g, f=f, b=b, m=m, alvo=alvo, fx=fx, sol=sol, alt=alt, refs=list(refs),
                rec=f'A frente exige lembrar a regra ({alvo[:90]}) sem trazer a resposta.',
                fb='Regra em linguagem simples' + ('; erro localizado' if erro_txt else '') +
                   ('; esquema' if esq else '') + '; Memorize com a formulação a guardar.')


