def completar_d(rub, obp_circ):
    """Rubrica e pendência de outras bancas dos D novos (preenchidas aqui para manter o texto acima legível)."""
    evid = {
     'D15': ('art. 35 e parágrafo único', 'retorno sem troca de faixa fixa o dado', 'exige aplicar a definição legal', 'a manobra e a justificativa a julgar'),
     'D16': ('art. 38, I e II', 'mão única e saída à esquerda explícitas', 'exige escolher a referência pelo sentido da pista', 'a avenida e a manobra'),
     'D17': ('Anexo I (parada; estacionamento) e art. 47', 'desembarque concluído e espera explícitos', 'exige classificar a imobilização pela finalidade', 'a espera do motorista de aplicativo, reescrita'),
     'D18': ('art. 29, X', 'sinalização do carro da frente e faixa livre explícitas', 'exige checar condições cumulativas', 'o comboio na rodovia'),
    }
    for x in D_NOVOS:
        fonte, det, op, cen = evid[x['k']]
        if not x['refs']:
            x['obp'] = obp_circ
        else:
            x.pop('obp', None)
        x['rb'] = rub(f'Conferido no CTB compilado: {fonte}.', f'Determinação: {det}; uma conclusão.', f'Operação: {op}.',
                      'PENDENTE: sem item Cebraspe oficial; inspiração geral declarada.', f'Autoria: cenário próprio ({cen}).',
                      'Feedback: regra, aplicação ao caso, confusão provável e Memorize.',
                      'Linguagem: frases curtas, termos explicados no verso (lindeiro, deslocamento lateral, parada).',
                      'Utilidade: cobre conteúdo do PDF ainda sem card de aplicação.')
    return D_NOVOS


# ---------------------------------------------------------------- cobertura total do PDF (p. 1–25)
def U(u, pag, conteudo, *cartoes, questao=None):
    d = dict(u=u, pag=pag, conteudo=conteudo, cartoes=list(cartoes))
    if questao:
        d['questao'] = questao
    return d


